// Collect all messages from all channels into one array
const allMessages = [];
for (const item of $input.all()) {
  if (item.json.messages) {
    for (const msg of item.json.messages) {
      allMessages.push({
        user: msg.user || 'unknown',
        text: msg.text || '',
        timestamp: msg.ts,
        channel: item.json.channel || 'unknown',
        thread_reply_count: msg.reply_count || 0,
        has_files: (msg.files && msg.files.length > 0) || false
      });
    }
  }
}

// Pass config through
const config = $input.first().json;
return [{
  json: {
    all_messages: allMessages,
    message_count: allMessages.length,
    scanner_prompt: config.scanner_prompt || $('CONFIG — Edit This Node').first().json.scanner_prompt,
    creator_prompt: config.creator_prompt || $('CONFIG — Edit This Node').first().json.creator_prompt,
    approval_channel: config.approval_channel || $('CONFIG — Edit This Node').first().json.approval_channel
  }
}];

