const response = $input.first().json;
const raw = response.content[0].text;
const config = $('Merge Messages').first().json;

try {
  // Handle potential markdown fences
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);

  if (!parsed.topics_found || parsed.topics_found.length === 0) {
    return [{ json: { has_topics: false, creator_prompt: config.creator_prompt, approval_channel: config.approval_channel } }];
  }

  return parsed.topics_found.map(topic => ({
    json: {
      has_topics: true,
      ...topic,
      creator_prompt: config.creator_prompt,
      approval_channel: config.approval_channel
    }
  }));
} catch (e) {
  return [{ json: { has_topics: false, error: e.message, raw_response: raw } }];
}

