const response = $input.first().json;
const raw = response.content[0].text;
const approval_channel = $('Parse Topics').first().json.approval_channel;

try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const post = JSON.parse(cleaned);

  // Format the Slack approval message
  const lines = [
    '*:mega: Social Post Draft for Approval*',
    '━━━━━━━━━━━━━━━━━━━━━━━━━',
    '',
    `*Topic:* ${post.topic_id || 'N/A'}`,
    '',
    '*--- LinkedIn Post ---*',
    '',
    post.linkedin_post ? post.linkedin_post.text : '_No LinkedIn post generated_',
    '',
    post.linkedin_post ? `_Hashtags:_ ${post.linkedin_post.hashtags.join(' ')}` : '',
    post.linkedin_post && post.linkedin_post.has_image ? `_Image:_ ${post.linkedin_post.image_notes}` : '',
    '',
    '*--- X / Twitter Post ---*',
    '',
    post.x_post ? post.x_post.text : '_No X post generated_',
    '',
    post.x_post && post.x_post.thread && post.x_post.thread.length > 0 ? '_Thread:_\n' + post.x_post.thread.map((t, i) => `${i+2}/ ${t}`).join('\n') : '',
    '',
    post.posting_notes ? `*Notes:* ${post.posting_notes}` : '',
    '',
    '━━━━━━━━━━━━━━━━━━━━━━━━━',
    'React to this message:',
    ':white_check_mark: Approve and post as-is',
    ':pencil2: Approve with edits (reply with changes)',
    ':x: Reject'
  ];

  return [{
    json: {
      approval_message: lines.filter(l => l !== undefined).join('\n'),
      approval_channel: approval_channel,
      linkedin_text: post.linkedin_post ? post.linkedin_post.text + '\n\n' + post.linkedin_post.hashtags.join(' ') : '',
      x_text: post.x_post ? post.x_post.text : '',
      x_thread: post.x_post && post.x_post.thread ? post.x_post.thread : [],
      topic_id: post.topic_id
    }
  }];
} catch (e) {
  return [{ json: { error: e.message, raw_response: raw, approval_channel: approval_channel } }];
}
